     9	import com.fasterxml.jackson.databind.JsonNode;
    10	import com.fasterxml.jackson.databind.ObjectMapper;
    11	import com.fasterxml.jackson.databind.node.ArrayNode;
    12	import com.fasterxml.jackson.databind.node.ObjectNode;
    13	
    14	/**
    15	 * Translates the JSON scenario protocol into MHPCO operations and back. The
    16	 * protocol field names are binding; what the office does with a step, and what
    17	 * it carries from one step to the next, is the {@link ClaimOffice}'s business.
    18	 */
    19	public class ClaimOfficeCli {
    20	
    21	    private static final ObjectMapper JSON = new ObjectMapper();
    22	
    23	    public void run(InputStream scenario, PrintStream results) {
    24	        try {
    25	            JsonNode input = JSON.readTree(scenario);
    26	            ClaimOffice office =
    27	                    new ClaimOffice(input.get("customer").get("yearsWithMHPCO").asInt());
    28	            ObjectNode output = JSON.createObjectNode();
    29	            ArrayNode resultsNode = output.putArray("results");
    30	            JsonNode steps = input.get("steps");
    31	            for (int stepIndex = 0; stepIndex < steps.size(); stepIndex++) {
    32	                JsonNode step = steps.get(stepIndex);
    33	                if ("claim".equals(step.get("op").asText())) {
    34	                    writeSettlement(office.settleClaim(step.get("policy").asInt(), damages(step)),
    35	                            resultsNode.addObject());
    36	                    continue;
    37	                }
    38	                resultsNode.addObject().put("premium",
    39	                        office.quote(stepIndex, insuredItems(step)));
    40	            }
    41	            results.print(JSON.writeValueAsString(output));
    42	        } catch (IOException e) {
    43	            throw new UncheckedIOException(e);
    44	        }
    45	    }
    46	
    47	    private static void writeSettlement(ClaimOffice.Settlement settlement, ObjectNode result) {
    48	        result.put("payout", settlement.payout().intValueExact());
    49	        result.put("remainingCap", settlement.remainingCap().intValueExact());
    50	    }
    51	
    52	    private static List<Damage> damages(JsonNode claimStep) {
    53	        List<Damage> damages = new ArrayList<>();
    54	        for (JsonNode damage : claimStep.get("incident").get("damages")) {
    55	            damages.add(new Damage(damage.get("itemType").asText(),
    56	                    new BigDecimal(damage.get("amount").asText())));
    57	        }
    58	        return damages;
    59	    }
    60	
    61	    private static List<InsuredItem> insuredItems(JsonNode quoteStep) {
    62	        List<InsuredItem> items = new ArrayList<>();
    63	        for (JsonNode item : quoteStep.get("items")) {
    64	            items.add(new InsuredItem(item.get("type").asText(),
    65	                    item.path("cursed").asBoolean(false),
    66	                    item.path("enchantment").asInt(0)));
    67	        }
    68	        return items;
    69	    }
    70	}
