     1	import java.math.BigDecimal;
     2	
     3	/**
     4	 * The MHPCO claim rules: what the office reimburses for a damage report against
     5	 * a policy, after the deductible and within the policy's payout cap.
     6	 *
     7	 * Two decisions the office revises on their own schedules meet here, in the
     8	 * order the specification fixes: its clause book states how much of a damage
     9	 * counts as reimbursable at all, and only then is the deductible borne. A new
    10	 * clause or a revised threshold is the clause book's business; repricing the
    11	 * deductible is this rule's.
    12	 *
    13	 * A payout is a payment out of the office, so its fraction of a G is rounded in
    14	 * the office's favor by {@link InOfficesFavor}.
    15	 */
    16	public class ClaimPolicy {
    17	
    18	    private static final BigDecimal DEDUCTIBLE_PER_DAMAGE = new BigDecimal("100");
    19	    private static final BigDecimal UNRULY_ITEM_REIMBURSEMENT_RATE = new BigDecimal("0.5");
    20	
    21	    /**
    22	     * The office reimburses the reimbursable part of a damage less the
    23	     * deductible, never below nothing.
    24	     */
    25	    public BigDecimal reimbursementFor(BigDecimal damageAmount, InsuredItem damagedItem) {
    26	        return InOfficesFavor.payment(reimbursableDamageUnderClauses(damageAmount, damagedItem)
    27	                .subtract(DEDUCTIBLE_PER_DAMAGE)
    28	                .max(BigDecimal.ZERO));
    29	    }
    30	
    31	    /**
    32	     * How much of a damage the office's clause book lets it count as
    33	     * reimbursable, read from the damaged item and settled before the
    34	     * deductible. The high-enchantment clause reimburses an unruly item's damage
    35	     * at a reduced rate; a damage no clause speaks to counts in full.
    36	     */
    37	    private static BigDecimal reimbursableDamageUnderClauses(BigDecimal damageAmount,
    38	            InsuredItem damagedItem) {
    39	        if (damagedItem.isTooUnrulyToReimburseInFull()) {
    40	            return damageAmount.multiply(UNRULY_ITEM_REIMBURSEMENT_RATE);
    41	        }
    42	        return damageAmount;
    43	    }
    44	}
