    96	    /**
    97	     * The office counts two items as alike when they are of exactly the same
    98	     * type, not merely of the same family: 2 runes and a moonstone are three
    99	     * loose components priced at 75 G, never a block, because a moonstone is not
   100	     * a rune. Widening "alike" to a family (rune-y, gemstone-y) would mean
   101	     * returning a family name here instead of the type itself.
   102	     */
   103	    private static String alikenessGroupOf(String itemType) {
   104	        return itemType;
   105	    }
   106	
   107	    /**
   108	     * What a holding of alike items of one type costs: the type's own rate per
   109	     * item, except that a block of components is offered at the block rate.
   110	     */
   111	    private static BigDecimal basePremium(String itemType, int count) {
   112	        if (qualifiesForBlockRate(itemType, count)) {
   113	            return COMPONENT_BLOCK_BASE_PREMIUM;
   114	        }
   115	        return TARIFF.get(itemType).basePremium().multiply(BigDecimal.valueOf(count));
   116	    }
   117	
   118	    /**
   119	     * The office grants the block rate only to a holding of exactly 3 alike
   120	     * components. It neither prices a part of a block at the block rate (4
   121	     * components are not a block) nor breaks a larger holding down into blocks
   122	     * (7 components are priced as 7, not as two blocks and one loose component).
   123	     * Main items are never blocked: 3 swords are 3 swords.
   124	     */
   125	    private static boolean qualifiesForBlockRate(String itemType, int alikeItemCount) {
   126	        return COMPONENT_TYPES.contains(itemType) && alikeItemCount == COMPONENT_BLOCK_SIZE;
   127	    }
